// Breaker - the settings catalog
//
// One line per setting. To add a setting, add a line:
//   {id, page, group, name, description, search words, control, spec, choices, recommended, flags, Windows page, detail}
//
// * spec is usually a registry spec the engine can read, write and undo by itself (see engine.cpp):
//     "HKCU\\path!Value=d:1/0?1"   REG_DWORD, on = 1, off = 0, missing means 1
//     "~" = value removed, "~~" = key removed, ";;" joins several values written together
//   Use "@" when the setting needs code: add a Handler with the same id in providers.cpp.
//   For CtlLink the spec is what to open (ms-settings: URI, program, "breaker:page", "action:name").
// * choices: "Label=value|Label=value" for CtlChoice, "min|max|step|unit" for CtlSlider.
// * recommended: the value Breaker suggests ("1"/"0" for toggles), or nullptr for no opinion.
#include "engine.h"

